from fastapi import APIRouter

from app.api.v1.endpoints import bookings, seats, events, health

api_router = APIRouter()

api_router.include_router(
    bookings.router,
    prefix="/bookings",
    tags=["bookings"]
)

api_router.include_router(
    seats.router,
    prefix="/seats",
    tags=["seats"]
)

api_router.include_router(
    events.router,
    prefix="/events",
    tags=["events"]
)

api_router.include_router(
    health.router,
    tags=["health"]
)
